#[test]
fn verhoeff_gives_the_references_verdict_on_every_listed_string() {
    for (index, (digits, verdict)) in VERDICTS.iter().enumerate() {
        assert_eq!(verhoeff_ok(digits), *verdict, "row {index}");
    }
}

#[test]
fn verhoeff_takes_every_listed_valid_number_and_refuses_each_single_digit_change() {
    for (index, number) in VALID_12.iter().enumerate() {
        assert!(verhoeff_ok(number), "valid number {index}");
        for at in 0..number.len() {
            for digit in '0'..='9' {
                if number.as_bytes()[at] as char == digit {
                    continue;
                }
                let mut changed: Vec<char> = number.chars().collect();
                changed[at] = digit;
                let changed: String = changed.into_iter().collect();
                assert!(!verhoeff_ok(&changed), "number {index} changed at {at}");
            }
        }
    }
}

