#[test]
fn every_country_of_the_reference_registry_has_its_length() {
    for (index, iban) in IBANS.iter().enumerate() {
        let text = format!("x {iban} y");
        assert_eq!(
            find_ibans(&text),
            vec![(2, 2 + iban.len())],
            "country {index}"
        );
        // One character more or less is a different length, which no country registers.
        assert!(
            find_ibans(&format!("x {iban}A y")).is_empty(),
            "longer {index}"
        );
        let shorter = &iban[..iban.len() - 1];
        assert!(
            find_ibans(&format!("x {shorter} y")).is_empty(),
            "shorter {index}"
        );
    }
}

