#[test]
fn every_state_format_gives_the_references_verdict_on_a_sample_and_its_neighbours() {
    for (index, (vat, verdict)) in VAT.iter().enumerate() {
        let text = format!("x {vat} y");
        let found = find_eu_vat(&text) == vec![(2, 2 + vat.len())];
        assert_eq!(found, *verdict, "row {index}");
    }
}
